export const resetRedux = () => ({
  type: RESET_REDUX,
});

export const addUser = (data) => ({
  type: CREATE_USER,
  payload: data,
});



export const getUsers = (phone) => ({
  type: GET_USERS,
  payload: phone,
});

// export const getUsersSuccess = (profiles) => ({
//     type: GET_USERS_SUCCESS,
//     payload: profiles,
// });

export const getUsersSuccess = (profiles) => async (dispatch, getState) => {
  dispatch({
    type: GET_USERS_SUCCESS,
    payload: profiles,
  });
  localStorage.setItem("users", JSON.stringify(getState().Users.users));
};

export const getUsersFailed = (message, errors) => ({
  type: GET_USERS_FAILED,
  payload: { message: message, errors: errors },
});

